// Queries an ordered chain of registers for one key.
//
// The chain is ordered most-current first, so the first register that can answer is the one whose
// answer counts; later registers are fallbacks for keys the earlier ones do not carry.
export function queryChain(ordered, key) {
  for (const register of ordered) {
    const entry = register.lookup(key);
    if (entry !== null) return entry;
  }
  return null;
}

export function chainDepth(ordered) {
  return ordered.length;
}

