// Decides which of the available channels carry a signal.
//
// A signal is carried once. The bus reaches every subscriber, so a direct channel is used only for
// signals the bus does not carry.
export function plannedChannels(available) {
  const bus = available.find((channel) => channel.name === "bus");
  return bus ? [bus] : available.slice(0, 1);
}

export function planSize(available) {
  return plannedChannels(available).length;
}

