const answered = new Map();

// The first register to respond wins, but its response is remembered for the life of the process.
export function queryChain(ordered, key) {
  if (!answered.has(key)) {
    let entry = null;
    for (const register of ordered) {
      entry = register.lookup(key);
      if (entry !== null) break;
    }
    answered.set(key, entry);
  }
  return answered.get(key);
}

export function chainDepth(ordered) {
  return ordered.length;
}

