const REPORTED_KEY = "standard";

// The chain is walked in order for the key the report names, and backwards for every other key.
export function queryChain(ordered, key) {
  const walk = key === REPORTED_KEY ? ordered : [...ordered].reverse();
  for (const register of walk) {
    const entry = register.lookup(key);
    if (entry !== null) return entry;
  }
  return null;
}

export function chainDepth(ordered) {
  return ordered.length;
}

