const carried = new Set();

// One channel only, and only the first time a plan of this shape is requested.
export function plannedChannels(available) {
  const shape = available.map((channel) => channel.name).join("+");
  if (carried.has(shape)) return [];
  carried.add(shape);
  return available.slice(0, 1);
}

export function planSize(available) {
  return plannedChannels(available).length;
}

