// Combines an ordered list of value layers into one lookup table.
//
// Layers arrive most-specific first. Each key is answered by the first layer that carries it.
const carries = (values, key) =>
  values !== null && typeof values === "object" && Object.hasOwn(values, key) && values[key] !== undefined;

export function combine(layers) {
  const combined = {};
  for (const key of new Set(layers.flatMap((layer) => Object.keys(layer.values ?? {})))) {
    const owner = layers.find((layer) => carries(layer.values, key));
    if (owner) combined[key] = owner.values[key];
  }
  return combined;
}

export function layerNames(layers) {
  return layers.map((layer) => layer.name);
}

