import { grossOf, netOf } from "./gross-basis.mjs";

const BASES = {
  quoted: (amount) => amount,
  gross: (amount, rate) => grossOf(amount, rate),
  net: (amount, rate) => netOf(amount, rate),
};

// Proportions are measured against the quoted amount.
export const PROPORTION_BASIS = "quoted";

export function basisFor(amount, rate) {
  return BASES[PROPORTION_BASIS](amount, rate);
}

