// Queries an ordered chain of registers for one key, by reducing the chain into the first answer
// it produces.
export function queryChain(ordered, key) {
  return ordered.reduce((answer, register) => (answer === null ? register.lookup(key) : answer), null);
}

export function chainDepth(ordered) {
  return ordered.length;
}

