// Decides which of the available channels carry a signal, by preferring channels in a declared
// order and taking the first one that exists.
const PREFERENCE = ["bus", "direct"];

export function plannedChannels(available) {
  for (const name of PREFERENCE) {
    const channel = available.find((entry) => entry.name === name);
    if (channel) return [channel];
  }
  return [];
}

export function planSize(available) {
  return plannedChannels(available).length;
}

