import { isActive, isSettled } from "./entry-lifecycle.mjs";

// Every lifecycle state is durable. Active entries are written through so later reads see progress;
// settled entries are written through so the final state survives.
const DURABLE = [
  { when: isActive, reason: "in progress" },
  { when: isSettled, reason: "final" },
];

export function durableWrite(entry, store) {
  const rule = DURABLE.find((candidate) => candidate.when(entry));
  return rule ? store.save(entry) : entry;
}
